-- Queries shaped like the API's (ooni/backend oonimeasurements), run as the oonimeasurements
-- user before and after each phase; their results must not change. One query per line;
-- each is run with FORMAT TSVWithNames.
SELECT measurement_uid, report_id, input, probe_cc, probe_asn, test_name, measurement_start_time, anomaly, confirmed, msm_failure FROM ooni.fastpath WHERE measurement_start_time >= '2026-09-30 22:00:00' AND measurement_start_time < '2026-10-01 02:00:00' AND probe_cc = 'IT' ORDER BY measurement_start_time DESC, measurement_uid LIMIT 100
SELECT probe_cc, test_name, toDate(measurement_start_time) AS day, count() AS measurement_count, countIf(anomaly = 't') AS anomaly_count, countIf(confirmed = 't') AS confirmed_count, countIf(msm_failure = 't') AS failure_count FROM ooni.fastpath WHERE measurement_start_time >= '2026-09-30' AND measurement_start_time < '2026-10-02' GROUP BY probe_cc, test_name, day ORDER BY probe_cc, test_name, day
SELECT COUNT(DISTINCT(probe_asn)) AS value, toStartOfMonth(measurement_start_time) AS date FROM ooni.fastpath WHERE measurement_start_time > '2026-01-01' AND measurement_start_time < '2026-11-01' GROUP BY date ORDER BY date
SELECT count() AS observation_count, probe_cc, IF(dns_failure IS NOT NULL, 'dns', IF(tcp_failure IS NOT NULL, 'tcp', IF(tls_failure IS NOT NULL, 'tls', 'none'))) AS failure FROM ooni.obs_web WHERE measurement_start_time >= '2026-09-30 22:00:00' AND measurement_start_time < '2026-10-01 02:00:00' GROUP BY probe_cc, failure ORDER BY probe_cc, failure
SELECT domain, probe_cc, count() AS n, round(avg(dns_blocked), 6) AS dns_blocked, round(avg(tcp_blocked), 6) AS tcp_blocked, round(avg(tls_blocked), 6) AS tls_blocked FROM ooni.analysis_web_measurement WHERE measurement_start_time >= '2026-09-30 22:00:00' AND measurement_start_time < '2026-10-01 02:00:00' GROUP BY domain, probe_cc ORDER BY n DESC, domain, probe_cc LIMIT 200
SELECT s3path, linenum FROM ooni.jsonl WHERE (report_id, input) IN (SELECT report_id, input FROM ooni.fastpath WHERE measurement_start_time >= '2026-10-01 01:00:00' AND measurement_start_time < '2026-10-01 01:01:00' ORDER BY measurement_uid LIMIT 20) ORDER BY s3path, linenum
SELECT category_code, count() AS n FROM ooni.fastpath INNER JOIN (SELECT url, category_code FROM ooni.citizenlab WHERE cc = 'ZZ' AND url NOT LIKE 'https://example.org/%') AS c ON fastpath.input = c.url WHERE measurement_start_time >= '2026-09-30 22:00:00' AND measurement_start_time < '2026-10-01 02:00:00' GROUP BY category_code ORDER BY category_code
SELECT * FROM ooni.obs_web WHERE measurement_start_time >= '2026-10-01 00:00:00' AND measurement_start_time < '2026-10-01 00:05:00' ORDER BY measurement_start_time, measurement_uid, observation_idx LIMIT 50 OFFSET 100
